-- ---------------------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------------------
SELECT 'vehicle rows present (want 12)' AS what, COUNT(*) AS n
FROM `vehicle_dbc` WHERE `ID` IN (659,665,924,1048,1049,1063,1094,1097,1132,1251,1294,1511)
UNION ALL SELECT 'seat rows present (want 33)', COUNT(*)
FROM `vehicleseat_dbc` WHERE `ID` IN (7570,7578,8134,8135,8390,8391,8392,8393,8394,8395,8396,8397,8398,8399,8400,8401,8406,8407,8429,8430,8494,8497,8589,8929,8930,8932,8935,8937,8938,8939,8940,9018,9551);

-- must be zero: an imported template whose VehicleId still has no row
SELECT 'PROBLEM: template with an unresolved VehicleId' AS problem,
       t.`entry`, t.`name`, t.`VehicleId`
FROM `creature_template` t
LEFT JOIN `vehicle_dbc` v ON v.`ID` = t.`VehicleId`
WHERE t.`entry` BETWEEN 4100000 AND 4199999
  AND t.`VehicleId` > 0 AND v.`ID` IS NULL;

-- must be zero: a vehicle pointing at a seat that does not exist
SELECT 'PROBLEM: vehicle references a missing seat' AS problem, s.`ID`, s.`seat`
FROM (
  SELECT `ID`, `SeatID_1` AS `seat` FROM `vehicle_dbc` WHERE `ID` IN (659,665,924,1048,1049,1063,1094,1097,1132,1251,1294,1511)
  UNION ALL SELECT `ID`, `SeatID_2` FROM `vehicle_dbc` WHERE `ID` IN (659,665,924,1048,1049,1063,1094,1097,1132,1251,1294,1511)
  UNION ALL SELECT `ID`, `SeatID_3` FROM `vehicle_dbc` WHERE `ID` IN (659,665,924,1048,1049,1063,1094,1097,1132,1251,1294,1511)
  UNION ALL SELECT `ID`, `SeatID_4` FROM `vehicle_dbc` WHERE `ID` IN (659,665,924,1048,1049,1063,1094,1097,1132,1251,1294,1511)
  UNION ALL SELECT `ID`, `SeatID_5` FROM `vehicle_dbc` WHERE `ID` IN (659,665,924,1048,1049,1063,1094,1097,1132,1251,1294,1511)
  UNION ALL SELECT `ID`, `SeatID_6` FROM `vehicle_dbc` WHERE `ID` IN (659,665,924,1048,1049,1063,1094,1097,1132,1251,1294,1511)
  UNION ALL SELECT `ID`, `SeatID_7` FROM `vehicle_dbc` WHERE `ID` IN (659,665,924,1048,1049,1063,1094,1097,1132,1251,1294,1511)
  UNION ALL SELECT `ID`, `SeatID_8` FROM `vehicle_dbc` WHERE `ID` IN (659,665,924,1048,1049,1063,1094,1097,1132,1251,1294,1511)
) s
WHERE s.`seat` > 0 AND s.`seat` NOT IN (SELECT `ID` FROM `vehicleseat_dbc`);
